script:
# Purchase Receipt - Move Bin to Receiving
# Triggered when Purchase Receipt is submitted
# Checks system idle, then commands robot to move bin to receiving station

# Check system idle - all signals must be 0 except PLC_CYCLE_RUNNING
conn = frappe.get_doc("Modbus Connection", "Roots Intralogistics Learning Lab")
for signal in conn.signals:
    if signal.signal_name == "PLC_CYCLE_RUNNING":
        continue  # OK if running
    try:
        current_value = signal.read_signal()
        if current_value == 1 or current_value == True:
            frappe.throw(f"Robot system busy ({signal.signal_name} active). Wait for current operation to complete.")
    except:
        pass  # Skip signals that can't be read

# Get target warehouse (bin) from first item
target_warehouse = doc.items[0].target_warehouse if doc.items else None
if not target_warehouse:
    frappe.throw("Purchase Receipt must specify target warehouse for items")

frappe.logger().info(f"📦 Purchase Receipt {doc.name} targeting warehouse: {target_warehouse}")

# Find bin signal and station signal
bin_signal = None
station_signal = None
for signal in conn.signals:
    if signal.warehouse == target_warehouse:
        bin_signal = signal
    if signal.warehouse == "Receiving Station 1 - GTAL":
        station_signal = signal

if not bin_signal:
    frappe.throw(f"No Modbus signal mapped to warehouse {target_warehouse}")
if not station_signal:
    frappe.throw("No Modbus signal found for Receiving Station 1")

frappe.logger().info(f"🤖 Commanding robot: {bin_signal.signal_name} + {station_signal.signal_name}")

# Write command signals
bin_signal.write_signal(True)
station_signal.write_signal(True)

frappe.msgprint(f"✅ Robot commanded to move {bin_signal.signal_name} to Receiving Station")

# POS Invoice - Move Bin to Pick & Pack
# Triggered when POS Invoice is submitted
# Checks system idle, finds bin with stock, then commands robot to move bin to pick & pack station

# Check system idle - all signals must be 0 except PLC_CYCLE_RUNNING
conn = frappe.get_doc("Modbus Connection", "Roots Intralogistics Learning Lab")
for signal in conn.signals:
    if signal.signal_name == "PLC_CYCLE_RUNNING":
        continue  # OK if running
    try:
        current_value = signal.read_signal()
        if current_value == 1 or current_value == True:
            frappe.throw(f"Robot system busy ({signal.signal_name} active). Wait for current operation to complete.")
    except:
        pass  # Skip signals that can't be read

# Find which bin has the items (simplified: use first item)
source_warehouse = None
for item in doc.items:
    # Query stock ledger to find which bin has this item
    bins = frappe.get_all(
        "Bin",
        filters={
            "item_code": item.item_code,
            "warehouse": ["like", "Storage Bin%"],
            "actual_qty": [">=", item.qty]
        },
        fields=["warehouse", "actual_qty"],
        order_by="actual_qty desc",
        limit=1
    )
    if bins:
        source_warehouse = bins[0].warehouse
        break

if not source_warehouse:
    frappe.throw("No storage bin found with sufficient stock for POS items")

frappe.logger().info(f"📦 POS Invoice {doc.name} picking from warehouse: {source_warehouse}")

# Find bin and station signals
bin_signal = None
station_signal = None
for signal in conn.signals:
    if signal.warehouse == source_warehouse:
        bin_signal = signal
    if signal.warehouse == "Pick and Pack Station 2 - GTAL":
        station_signal = signal

if not bin_signal:
    frappe.throw(f"No Modbus signal mapped to warehouse {source_warehouse}")
if not station_signal:
    frappe.throw("No Modbus signal found for Pick and Pack Station 2")

frappe.logger().info(f"🤖 Commanding robot: {bin_signal.signal_name} + {station_signal.signal_name}")

# Write command signals
bin_signal.write_signal(True)
station_signal.write_signal(True)

frappe.msgprint(f"✅ Robot commanded to move {bin_signal.signal_name} to Pick & Pack Station")
